// ---------------------------------------------------------------------------
// RECOMMENDED: build the whole frame as ONE G4MultiUnion solid.
//
// G4MultiUnion::Inside() returns kInside as soon as ANY constituent contains
// the point, so the 226 interpenetrating pairs are handled exactly.  It holds
// a G4Voxelizer internally, so queries are voxel-local rather than O(N).
//
// TRANSFORM CONVENTION -- differs from G4PVPlacement:
//   G4MultiUnion::AddNode takes the FORWARD transform (local -> global);
//   G4PVPlacement takes the INVERSE rotation.  Do not copy one into the other.
// ---------------------------------------------------------------------------
G4MultiUnion* BuildANNIEInnerStructureSolid(const G4String& name)
{
  G4MultiUnion* frame = new G4MultiUnion(name);

  for (std::size_t i = 0; i < kNMembers; ++i) {
    const Member& m = kMembers[i];
    char nm[160];
    std::snprintf(nm, sizeof(nm), "%s_m%u", name.c_str(), (unsigned)i);

    G4VSolid* s = MakeMemberSolid(m, G4String(nm));

    CLHEP::HepRotation R(CLHEP::Hep3Vector(m.e1[0], m.e1[1], m.e1[2]),
                         CLHEP::Hep3Vector(m.e2[0], m.e2[1], m.e2[2]),
                         CLHEP::Hep3Vector(m.d[0],  m.d[1],  m.d[2]));
    frame->AddNode(*s, G4Transform3D(R, G4ThreeVector(m.c[0] * CLHEP::mm,
                                                      m.c[1] * CLHEP::mm,
                                                      m.c[2] * CLHEP::mm)));
  }

  frame->Voxelize();   // MANDATORY -- without it every query degrades to O(N)
  return frame;
}

// Drop-in replacement for the parser.Read()/GetWorldVolume() block in
// GeoANNIEFactory::ConstructANNIEInnerStructure().  Returns the logical volume
// to place with your existing rotm / StructureCenter.
G4LogicalVolume* MakeANNIEInnerStructureLV(G4Material* steel,
                                           G4OpticalSurface* wrapper)
{
  G4MultiUnion* frame = BuildANNIEInnerStructureSolid("InnerStructure");
  G4LogicalVolume* lv = new G4LogicalVolume(frame, steel, "innerstructure_log");
  if (wrapper != nullptr) {
    new G4LogicalSkinSurface("innerStructureSurface", lv, wrapper);
  }
  return lv;
}

// ---------------------------------------------------------------------------
// DEBUG/VISUALISATION ONLY -- one placement per member.
// This WILL report overlaps (226 pairs) and WILL reproduce zero-step failures.
// Useful only to eyeball individual members in a viewer.
// ---------------------------------------------------------------------------
std::vector<G4VPhysicalVolume*>
BuildANNIEInnerStructureAsPlacements(G4LogicalVolume* mother,
                                     G4RotationMatrix* structRot,
                                     const G4ThreeVector& structCentre,
                                     G4Material* steel,
                                     G4OpticalSurface* wrapper)
{
  std::vector<G4VPhysicalVolume*> placed;
  std::map<std::tuple<int,int,int,int>, G4LogicalVolume*> cache;

  // G4PVPlacement's rotation argument is the INVERSE of the object rotation,
  // so the structure's own object rotation is structRot^-1.
  CLHEP::HepRotation Rstruct;                       // identity by default
  if (structRot != nullptr) { Rstruct = structRot->inverse(); }

  for (std::size_t i = 0; i < kNMembers; ++i) {
    const Member& m = kMembers[i];
    auto key = std::make_tuple(int(m.W1*100), int(m.W2*100),
                               int(m.L*100),  int(m.wall*100) + 1000000*m.shape);
    G4LogicalVolume* lv = nullptr;
    auto it = cache.find(key);
    if (it != cache.end()) {
      lv = it->second;
    } else {
      char nm[160];
      std::snprintf(nm, sizeof(nm), "IS_%.0fx%.0fx%.0f_t%.0f",
                    m.W1, m.W2, m.L, m.wall*10);
      G4VSolid* solid = MakeMemberSolid(m, G4String(nm));
      lv = new G4LogicalVolume(solid, steel, nm);
      if (wrapper != nullptr) {
        new G4LogicalSkinSurface(G4String(nm) + "_surf", lv, wrapper);
      }
      cache[key] = lv;
    }
    // Compose member -> GDML -> mother.
    //   p_mother = Rstruct * (Ri * p_local + c_i) + structCentre
    // so the total object rotation is Rstruct*Ri and G4PVPlacement wants its
    // inverse, Ri^-1 * structRot.
    CLHEP::HepRotation Ri(CLHEP::Hep3Vector(m.e1[0], m.e1[1], m.e1[2]),
                          CLHEP::Hep3Vector(m.e2[0], m.e2[1], m.e2[2]),
                          CLHEP::Hep3Vector(m.d[0],  m.d[1],  m.d[2]));
    CLHEP::HepRotation Rinv = Ri.inverse();
    if (structRot != nullptr) { Rinv = Rinv * (*structRot); }
    G4RotationMatrix* rot = new G4RotationMatrix(Rinv);

    G4ThreeVector cLocal(m.c[0]*CLHEP::mm, m.c[1]*CLHEP::mm, m.c[2]*CLHEP::mm);
    G4ThreeVector cMother = Rstruct * cLocal + structCentre;

    char pnm[160];
    std::snprintf(pnm, sizeof(pnm), "IS_member_%u", (unsigned)i);
    placed.push_back(new G4PVPlacement(
        rot, cMother, lv, pnm, mother, false, int(i), false));
  }
  return placed;
}